    "verify_code": "import sympy as sp\nfreqs = [4, 12, 20, 8, 6]\nupper_limits = [0, 20, 40, 60, 80, 100]\ncum_freq = [0]\nfor f in freqs:\n    cum_freq.append(cum_freq[-1] + f)\nprint(\"Points to plot:\", list(zip(upper_limits, cum_freq)))\nassert cum_freq[-1] == 50",
